def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MIN_SUPPLY = 15
    MAX_SUPPLY = 25

    supply = float(day_context['supply'])
    day = int(day_context['day'])
    hp = my_status['hp']
    budget = my_status['budget']
    no_water = my_status['no_water_days']

    if budget <= 0:
        return 0.0

    alive = []
    for oid, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append((oid, opp))

    if not alive:
        return float(min(budget, 18.0))

    slots = max(1, int(supply / WATER_REQ))
    opp_bids = []
    desperate_count = 0
    rich_conservative = 0
    for oid, opp in alive:
        prev = opp.get('previous_trace', {}) or {}
        bid = prev.get('bid')
        if bid is not None:
            opp_bids.append(float(bid))
        if opp.get('hp', 0) <= 3 or opp.get('no_water_days', 0) >= 1:
            desperate_count += 1
        if opp.get('budget', 0) > 300 and opp.get('daily_salary', 0) >= 70:
            rich_conservative += 1

    highest_prev = max(opp_bids) if opp_bids else 0.0
    second_prev = 0.0
    if len(opp_bids) >= 2:
        sorted_bids = sorted(opp_bids, reverse=True)
        second_prev = sorted_bids[int(1)]

    urgency = 0
    if hp <= 2:
        urgency += 3
    elif hp <= 4:
        urgency += 2
    elif hp <= 6:
        urgency += 1
    if no_water >= 2:
        urgency += 3
    elif no_water >= 1:
        urgency += 2

    tight = slots <= 1
    very_tight = supply <= 16

    base = 16.0
    if slots >= 2:
        base = 12.0
    if slots == 1:
        base = 24.0
    if very_tight:
        base += 6.0

    if highest_prev >= 500:
        pressure_bid = 46.0
    elif highest_prev >= 130:
        pressure_bid = 58.0
    elif highest_prev >= 90:
        pressure_bid = min(72.0, highest_prev + 2.0)
    elif highest_prev >= 50:
        pressure_bid = highest_prev + 1.5
    elif highest_prev > 0:
        pressure_bid = max(base, highest_prev + 1.0)
    else:
        pressure_bid = base

    bid = max(base, pressure_bid)

    if desperate_count >= slots:
        bid += 10.0
    elif desperate_count > 0:
        bid += 4.0

    if rich_conservative >= 1 and highest_prev <= 140:
        bid += 3.0

    if urgency >= 5:
        bid = max(bid, 82.0)
    elif urgency >= 3:
        bid = max(bid, 62.0)
    elif urgency >= 1:
        bid = max(bid, 42.0)

    if day >= 8:
        bid += 6.0
    if day >= 9 and hp <= 5:
        bid += 8.0

    reserve = 0.0
    if day <= 7:
        reserve = 20.0
    elif day == 8:
        reserve = 10.0

    affordable = max(0.0, budget - reserve)
    if urgency >= 5:
        affordable = budget

    bid = min(bid, affordable if affordable > 0 else budget)
    bid = min(bid, budget)
    if bid < 0:
        bid = 0.0

    return float(round(bid, 2))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context.get('supply', 0.0))
    day = int(day_context.get('day', 0))

    hp = float(my_status.get('hp', 0.0))
    budget = float(my_status.get('budget', 0.0))
    no_water_days = int(my_status.get('no_water_days', 0))

    alive_opps = []
    for oid, o in opponents_status.items():
        if o.get('alive', False):
            alive_opps.append((oid, o))

    if not alive_opps:
        cap = min(budget, DAILY_SALARY * 0.4)
        return max(0.0, cap)

    # Extract yesterday bids from previous_trace only
    prev_bids = []
    for oid, o in alive_opps:
        prev = o.get('previous_trace', {})
        b = prev.get('bid', None)
        if b is not None:
            try:
                prev_bids.append(float(b))
            except Exception:
                pass

    highest_prev_bid = max(prev_bids) if prev_bids else 0.0

    # Pressure model: if someone was bidding far above typical salary, assume they will bid to secure water.
    # We counter with moderate bids unless our survival is at risk.
    tight_supply = supply <= (MIN_SUPPLY + 1.0)
    very_tight_supply = supply <= (MIN_SUPPLY + 0.2)

    # Base bid depends on our HP/no-water risk.
    if hp <= 2 or no_water_days >= 2:
        base = DAILY_SALARY * (0.85 if tight_supply else 0.65)
    elif hp <= 4 or no_water_days == 1:
        base = DAILY_SALARY * (0.65 if tight_supply else 0.50)
    else:
        base = DAILY_SALARY * (0.55 if tight_supply else 0.40)

    # If yesterday someone overbid massively, don't chase their peak; instead slightly shade upward when tight.
    if highest_prev_bid >= DAILY_SALARY * 1.5:
        if very_tight_supply:
            base = max(base, DAILY_SALARY * 0.75)
        else:
            base = max(base, DAILY_SALARY * 0.60)

    # If yesterday bids were low, we can bid near base; if bids were moderately high, nudge up.
    elif highest_prev_bid >= DAILY_SALARY * 0.9:
        base = max(base, DAILY_SALARY * (0.60 if tight_supply else 0.50))

    # Convert supply into a small adjustment: lower supply -> higher chance we need to win.
    # Use explicit int indexing safeguard via simple arithmetic only.
    supply_ratio = (supply - MIN_SUPPLY) / (MAX_SUPPLY - MIN_SUPPLY) if MAX_SUPPLY > MIN_SUPPLY else 0.5
    # supply_ratio in [0,1]; when low, add pressure
    pressure = (1.0 - max(0.0, min(1.0, supply_ratio)))
    base = base * (1.0 + 0.25 * pressure)

    # Final cap by budget
    bid = min(budget, base)

    # Ensure non-negative
    if bid < 0.0:
        bid = 0.0

    return float(bid)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 150
    EPISODE_DAYS = 10

    alive_opponents = [o for o in opponents_status.values() if o['alive']]
    num_alive_opponents = len(alive_opponents)

    if num_alive_opponents == 0:
        return min(my_status['budget'], DAILY_SALARY * 0.4)

